-- AfriDetect Mat — initial schema
-- Generated by hand from src/db/schema.ts (drizzle-kit could not run in this
-- environment because npm postinstall scripts are blocked; see README).

CREATE TABLE IF NOT EXISTS "facilities" (
  "id" text PRIMARY KEY,
  "name" text NOT NULL,
  "kind" text NOT NULL,
  "location" text NOT NULL,
  "beds" integer NOT NULL DEFAULT 0,
  "staff_count" integer NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "clinicians" (
  "id" text PRIMARY KEY,
  "name" text NOT NULL,
  "role" text NOT NULL,
  "initials" text NOT NULL,
  "facility_id" text NOT NULL,
  "email" text UNIQUE,
  "password_hash" text
);

CREATE TABLE IF NOT EXISTS "staff" (
  "id" text PRIMARY KEY,
  "name" text NOT NULL,
  "role" text NOT NULL,
  "email" text NOT NULL,
  "status" text NOT NULL DEFAULT 'active',
  "patients" integer NOT NULL DEFAULT 0,
  "facility_id" text NOT NULL
);

CREATE TABLE IF NOT EXISTS "patients" (
  "id" text PRIMARY KEY,
  "slug" text NOT NULL UNIQUE,
  "name" text NOT NULL,
  "age" integer NOT NULL,
  "weeks" integer NOT NULL,
  "days" integer NOT NULL,
  "edd" text NOT NULL,
  "phone" text NOT NULL,
  "clinician_id" text NOT NULL,
  "facility_id" text NOT NULL,
  "status" text NOT NULL,
  "last_check_in" timestamptz NOT NULL,
  "history" text NOT NULL DEFAULT '',
  "gravida" integer NOT NULL DEFAULT 1,
  "para" integer NOT NULL DEFAULT 0,
  "blood_group" text NOT NULL DEFAULT 'Unknown',
  "genotype" text NOT NULL DEFAULT 'Unknown',
  "allergies" text[] NOT NULL DEFAULT '{}',
  "conditions" text[] NOT NULL DEFAULT '{}',
  "urine_protein" text,
  "care_plan" text NOT NULL DEFAULT '',
  "risk_factors" text[] NOT NULL DEFAULT '{}',
  "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS "readings" (
  "id" serial PRIMARY KEY,
  "patient_id" text NOT NULL,
  "at" timestamptz NOT NULL,
  "systolic" integer NOT NULL,
  "diastolic" integer NOT NULL,
  "source" text NOT NULL DEFAULT 'patient',
  "verified" boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS "patient_notes" (
  "id" text PRIMARY KEY,
  "patient_id" text NOT NULL,
  "at" timestamptz NOT NULL,
  "author" text NOT NULL,
  "body" text NOT NULL
);

CREATE TABLE IF NOT EXISTS "appointments" (
  "id" text PRIMARY KEY,
  "patient_id" text NOT NULL,
  "patient_name" text NOT NULL,
  "reason" text NOT NULL,
  "at" timestamptz NOT NULL,
  "clinician_id" text NOT NULL,
  "state" text NOT NULL DEFAULT 'upcoming',
  "location" text NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "alerts" (
  "id" text PRIMARY KEY,
  "patient_id" text NOT NULL,
  "patient_name" text NOT NULL,
  "severity" text NOT NULL,
  "title" text NOT NULL,
  "detail" text NOT NULL DEFAULT '',
  "at" timestamptz NOT NULL,
  "assigned_to" text,
  "acknowledged" boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS "referrals" (
  "id" text PRIMARY KEY,
  "patient_id" text NOT NULL,
  "patient_name" text NOT NULL,
  "destination" text NOT NULL,
  "reason" text NOT NULL,
  "at" timestamptz NOT NULL,
  "state" text NOT NULL DEFAULT 'in-progress',
  "urgency" text NOT NULL DEFAULT 'routine'
);

CREATE TABLE IF NOT EXISTS "activities" (
  "id" text PRIMARY KEY,
  "at" timestamptz NOT NULL,
  "actor" text NOT NULL,
  "action" text NOT NULL,
  "subject" text
);

CREATE TABLE IF NOT EXISTS "notifications" (
  "id" text PRIMARY KEY,
  "at" timestamptz NOT NULL,
  "title" text NOT NULL,
  "body" text NOT NULL,
  "kind" text NOT NULL DEFAULT 'system',
  "read" boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS "access_requests" (
  "id" text PRIMARY KEY,
  "patient_id" text NOT NULL,
  "patient_name" text NOT NULL,
  "scope" text NOT NULL,
  "note" text NOT NULL DEFAULT '',
  "requested_at" timestamptz NOT NULL,
  "status" text NOT NULL DEFAULT 'pending'
);

CREATE TABLE IF NOT EXISTS "check_ins" (
  "id" text PRIMARY KEY,
  "at" timestamptz NOT NULL,
  "feeling" text NOT NULL,
  "symptoms" text[] NOT NULL DEFAULT '{}',
  "note" text NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "threads" (
  "id" text PRIMARY KEY,
  "name" text NOT NULL,
  "role" text NOT NULL,
  "note" text NOT NULL DEFAULT '',
  "unread" integer NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "messages" (
  "id" text PRIMARY KEY,
  "thread_id" text NOT NULL,
  "from_role" text NOT NULL,
  "body" text NOT NULL,
  "at" timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS "mother_profile" (
  "id" integer PRIMARY KEY DEFAULT 1,
  "setup_complete" boolean NOT NULL DEFAULT false,
  "name" text NOT NULL,
  "phone" text NOT NULL,
  "address" text NOT NULL DEFAULT '',
  "next_of_kin" text NOT NULL DEFAULT '',
  "language" text NOT NULL DEFAULT 'English',
  "consent_share" boolean NOT NULL DEFAULT true,
  "patient_id" text NOT NULL
);

CREATE INDEX IF NOT EXISTS "readings_patient_idx" ON "readings" ("patient_id", "at" DESC);
CREATE INDEX IF NOT EXISTS "notes_patient_idx" ON "patient_notes" ("patient_id", "at" DESC);
CREATE INDEX IF NOT EXISTS "appointments_at_idx" ON "appointments" ("at");
CREATE INDEX IF NOT EXISTS "alerts_open_idx" ON "alerts" ("acknowledged", "at" DESC);
CREATE INDEX IF NOT EXISTS "messages_thread_idx" ON "messages" ("thread_id", "at");
CREATE INDEX IF NOT EXISTS "patients_facility_idx" ON "patients" ("facility_id");
